import { ExternalLink, Lock } from 'lucide-react'
import { useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { BRAND } from '@/brand'
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet'

export type PaymentReturn = 'success' | 'cancel'

/**
 * The payment form, inside the app: ChargX's own page in a frame in a tall
 * sheet, so paying never leaves the app. The card is typed on ChargX's page,
 * which the app can't read. When ChargX sends the customer to the return page
 * (/pay-return.html, generated by vite.config.ts's payReturnPage), that page tells this one
 * the result and the sheet closes; "paid" itself still comes from the webhook,
 * never from this message.
 *
 * A link opens the same page in the browser, for when a phone won't show
 * payment inside a frame (Apple Pay may not appear there).
 */
export function PaymentFrame({
  open,
  url,
  fallbackUrl,
  orderNumber,
  onOpenChange,
  onReturn,
}: {
  open: boolean
  url: string
  fallbackUrl: string
  orderNumber: string
  onOpenChange: (open: boolean) => void
  onReturn: (result: PaymentReturn) => void
}) {
  const { t } = useTranslation()

  useEffect(() => {
    if (!open) return
    function onMessage(event: MessageEvent) {
      // Only our own return page, for this order.
      if (event.origin !== window.location.origin) return
      const data: unknown = event.data
      if (typeof data !== 'object' || data === null) return
      const { type, result, order } = data as Record<string, unknown>
      if (type !== 'peptidescr-pay-return' || order !== orderNumber) return
      onReturn(result === 'success' ? 'success' : 'cancel')
    }
    window.addEventListener('message', onMessage)
    return () => window.removeEventListener('message', onMessage)
  }, [open, orderNumber, onReturn])

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="h-[92dvh]">
        <SheetHeader className="pr-14">
          <SheetTitle className="flex items-center gap-2 text-lg">
            <Lock aria-hidden className="size-4 text-primary" />
            {t('checkout.securePayment')}
          </SheetTitle>
          <SheetDescription>{t('checkout.securePaymentNote', { store: BRAND.store.name })}</SheetDescription>
        </SheetHeader>
        <iframe
          src={url}
          title={t('checkout.securePayment')}
          allow="payment *"
          referrerPolicy="strict-origin-when-cross-origin"
          className="min-h-0 w-full flex-1 border-0 bg-white"
        />
        <a
          href={fallbackUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="flex min-h-11 shrink-0 items-center justify-center gap-1.5 px-5 text-xs font-semibold text-muted-foreground"
        >
          <ExternalLink aria-hidden className="size-3.5" />
          {t('checkout.openPaymentInBrowser')}
        </a>
      </SheetContent>
    </Sheet>
  )
}
